class Solution {
public:
    vector<vector<int>> kSmallestPairs(vector<int>& nums1, vector<int>& nums2, int k) {
        int n1 = nums1.size(), n2 = nums2.size();
        vector<vector<int>> result;
        if (n1 == 0 || n2 == 0 || k == 0) return result;

        auto cmp = [](const tuple<long long,int,int>& a, const tuple<long long,int,int>& b) {
            return get<0>(a) > get<0>(b);
        };
        priority_queue<tuple<long long,int,int>,
                       vector<tuple<long long,int,int>>,
                       decltype(cmp)> pq(cmp);

        int initCount = min(k, n1);
        for (int i = 0; i < initCount; i++) {
            pq.push(make_tuple((long long)nums1[i] + nums2[0], i, 0));
        }

        while (!pq.empty() && (int)result.size() < k) {
            auto top = pq.top();
            pq.pop();
            int i = get<1>(top);
            int j = get<2>(top);
            result.push_back({nums1[i], nums2[j]});
            if (j + 1 < n2) {
                pq.push(make_tuple((long long)nums1[i] + nums2[j + 1], i, j + 1));
            }
        }

        return result;
    }
};
